          alt: "ตารางสัญลักษณ์ 8 ตัว แถวบน: ไดโอด (สามเหลี่ยมชี้ขวาชนขีด A ซ้าย K ขวา), ซีเนอร์ (ขีดแคโทดงอปลายเป็นรูปตัว Z), LED (ไดโอดมีลูกศรสองเส้นชี้ออก), โฟโตไดโอด (ลูกศรสองเส้นชี้เข้า) แถวล่าง: ชอตต์กี (ขีดแคโทดงอเป็นรูปตัว S), NPN (วงกลม ขา B ซ้าย C บน E ล่าง ลูกศรที่ขา E ชี้ออก), PNP (ลูกศรที่ขา E ชี้เข้า), SCR (ไดโอดแนวตั้ง A บน K ล่าง มีขาเกต G ออกจากด้านแคโทด)",
