          alt: "หม้อแปลงลดแรงดัน ด้านปฐมภูมิ 230 V ไฟสลับ สายน้ำตาลและสายฟ้า มีหมายเหตุครูต่อ ด้านทุติยภูมิ 12 V ไฟสลับ ต่อผ่านไดโอด D 1N4007 ไปยังตัวต้านทานโหลด R_L 1 kΩ ขั้วบวกอยู่บน ลูกศรกระแสไหลในช่วงซีกบวก ด้านล่างมีกรอบรูปคลื่นอินพุตเป็นไซน์ 2 ไซเคิล และกรอบเอาต์พุตบน R_L มีเฉพาะยอดคลื่นซีกบวก ซีกลบเป็นศูนย์",
